"""The sample policy, catalog, and principals the demo ships, written to
disk (not just constructed in memory) so running `custody demo` leaves
behind something you can open and read, same as a real deployment would.
"""

from __future__ import annotations

CATALOG_YAML = """\
# Synthetic tumor registry, generated by `custody demo`. See
# docs/data-use-agreements... no, wait, this is Custody's own demo data,
# not UNMIRI's: every row here is generated, fixed seed, nothing real.
datasets:
  - id: tumor_registry_deidentified
    path: data/tumor_registry_deidentified.synthetic.csv
    format: csv
    data_class: deidentified

  - id: tumor_registry_identified
    path: data/tumor_registry_identified.synthetic.csv
    format: csv
    data_class: identified
    columns:
      mrn: direct_identifier
      patient_name: direct_identifier
"""

POLICY_YAML = """\
rules:
  - id: catalog-list-ok
    when: { tool: catalog.list }
    decision: allow

  - id: no-egress
    when: { egress: true }
    decision: deny

  - id: deid-query-ok
    when: { tool: sql.query, max_data_class: deidentified }
    decision: allow

  - id: identified-query-needs-approval
    when: { tool: sql.query, min_data_class: identified }
    decision: require_approval
    approvals: { count: 1, roles: [data_steward] }

  - id: files-write-ok
    when: { tool: files.write }
    decision: allow

  - id: export-two-person
    when: { tool: files.export, min_data_class: limited_data_set }
    decision: require_approval
    approvals: { count: 2, roles: [data_steward, privacy_officer] }

  - id: shell-run-ok
    when: { tool: shell.run }
    decision: allow

default: deny

model_allowlist:
  synthetic: ["*"]
  deidentified: ["*"]
  limited_data_set: ["ollama/*", "bedrock-baa/*"]
  identified: ["ollama/*", "bedrock-baa/*"]
"""

PRINCIPALS_YAML = """\
principals:
  - id: dr_steward
    roles: [data_steward]
  - id: dr_privacy
    roles: [privacy_officer]
"""
